using namespace lazyipdca::qcqp;
namespace {
using Matrix=std::vector<Vec>;using Clock=std::chrono::steady_clock;
constexpr double tolerance=1e-6;
bool all_finite(const Vec&v){for(double x:v)if(!std::isfinite(x))return false;return true;}
double l2(const Vec& a){long double v=0;for(double x:a)v+=(long double)x*x;return std::sqrt(v);}
double elapsed(Clock::time_point start){return std::chrono::duration<double>(Clock::now()-start).count();}
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
struct Counters {int newton=0,normal=0,dual_fit=0,dual_basis=0,factors=0,solves=0,line_trials=0;double max_linear_audit=0,max_forcing_ratio=0,max_normal_linear_residual=0;};
struct Eigen {Vec values;Matrix vectors;};
// Small symmetric Jacobi selects a bounded rank/forcing subspace only. It is
// never used as a certificate of convexity or as the Newton linear solver.
Eigen jacobi(Matrix a,const std::function<bool()>& open) {
 const int n=a.size();Matrix v(n,Vec(n));for(int i=0;i<n;++i)v[i][i]=1;
 for(int sweep=0;sweep<100;++sweep){require(open(),"Jacobi deadline");double off=0,scale=1;for(int i=0;i<n;++i){scale=std::max(scale,std::abs(a[i][i]));for(int j=i+1;j<n;++j)off=std::max(off,std::abs(a[i][j]));}
  if(off<=2*std::numeric_limits<double>::epsilon()*scale)break;
  for(int p=0;p<n;++p)for(int q=p+1;q<n;++q){if(q==p+1)require(open(),"Jacobi deadline");const double b=a[p][q];if(std::abs(b)<=std::numeric_limits<double>::epsilon()*scale)continue;
   const double t=(a[q][q]-a[p][p])/(2*b);const double z=std::copysign(1.,t)/(std::abs(t)+std::hypot(1.,t));const double c=1/std::sqrt(1+z*z),s=z*c;
   const double ap=a[p][p],aq=a[q][q];a[p][p]=ap-z*b;a[q][q]=aq+z*b;a[p][q]=a[q][p]=0;
   for(int k=0;k<n;++k)if(k!=p&&k!=q){const double x=a[k][p],y=a[k][q];a[k][p]=a[p][k]=c*x-s*y;a[k][q]=a[q][k]=s*x+c*y;}
   for(int k=0;k<n;++k){const double x=v[k][p],y=v[k][q];v[k][p]=c*x-s*y;v[k][q]=s*x+c*y;}
  }
 }
 Vec w(n);for(int i=0;i<n;++i)w[i]=a[i][i];std::vector<int> order(n);std::iota(order.begin(),order.end(),0);std::stable_sort(order.begin(),order.end(),[&](int i,int j){return w[i]<w[j];});Eigen e;e.values.resize(n);e.vectors.assign(n,Vec(n));for(int j=0;j<n;++j){e.values[j]=w[order[j]];for(int i=0;i<n;++i)e.vectors[i][j]=v[i][order[j]];}return e;
}
Settings strict_settings(){Settings s;s.linear_backend="mumps";s.linear_metis=true;s.kkt_adaptive_regularization=false;s.kkt_primal_regularization=0;s.kkt_dual_regularization=0;s.kkt_backward_error_reject=1e-7;s.termination_test="project";s.feasibility_tolerance=s.stationarity_tolerance=s.dual_infeasibility_tolerance=s.complementarity_tolerance=tolerance;s.acceptable_iterations=0;s.acceptable_on_failure=false;return s;}
// Original-input-only audit: retain the same core and fixed-bound policy,
// without pulling the unused presolve/ordinary-optimizer dispatcher into this tool.
bool direct_original_audit(const QCQPProblem& p,const Settings& settings,Result& r,bool reconstruct_fixed=true){
 detail::DirectOriginalAuditView view{p,r};
 return detail::audit_original_termination_impl(p,settings,r,view,nullptr,reconstruct_fixed,nullptr);
}
struct Context {Settings settings=strict_settings();Clock::time_point started;double budget;Counters counts;Context(Clock::time_point t,double s):started(t),budget(s){}bool open()const{return elapsed(started)<budget;}
 Vec solve(const Matrix& a,const Vec& rhs,int negative,const char* role){require(open(),"finisher deadline before factor");require(a.size()<=1024,"native finisher system dimension exceeds bounded storage");const int n=a.size();require(all_finite(rhs),"nonfinite finisher right-hand side");for(const auto&row:a)require(row.size()==a.size()&&all_finite(row),"invalid finisher matrix");require(n>0&&rhs.size()==a.size()&&negative>=0&&negative<=n,"invalid small original-KKT linear system");std::vector<SymmetricTriplet> entries;entries.reserve(std::size_t(n)*(std::size_t(n)+1)/2);for(int i=0;i<n;++i)for(int j=i;j<n;++j)if(a[i][j]!=0||i==j)entries.push_back({i,j,a[i][j]});std::string message;auto f=make_symmetric_factorization(settings,message);require(bool(f),"MUMPS factory unavailable");++counts.factors;if(!f->factor(n,n-negative,entries,message))throw std::runtime_error(std::string(role)+" factor: "+message);require(open(),"finisher deadline after factor");require(f->last_primal_regularization()==0&&f->last_dual_regularization()==0,"unexpected backend shift in signed finisher system");Vec sol=rhs;++counts.solves;if(!f->solve(sol,message))throw std::runtime_error(std::string(role)+" solve: "+message);require(open(),"finisher deadline after solve");require(all_finite(sol),"nonfinite native finisher solution");double error=0,denom=0;for(int i=0;i<n;++i){long double r=-rhs[i],magnitude=std::abs(rhs[i]);for(int j=0;j<n;++j){r+=(long double)a[i][j]*sol[j];magnitude+=std::abs((long double)a[i][j]*sol[j]);}error=std::max(error,double(std::abs(r)));denom=std::max(denom,double(magnitude));}const double audit=error/std::max(1.,denom);counts.max_linear_audit=std::max(counts.max_linear_audit,audit);require(std::isfinite(audit)&&audit<=1e-7,"expanded original finisher linear audit failed");return sol;}
};
struct Point {Vec x,lambda,z;};
struct State {Vec h,g,rd,objective_gradient;Matrix jh,jg;};
struct Problem {
 const QCQPProblem& p;std::vector<QuadraticFunction> inequalities;std::vector<int> kinds,origins,free;Vec hs,gs;double sf;
 Problem(const QCQPProblem& input,const Point& warm):p(input){require(p.n>0&&p.n<=128,"native feasible finisher supports n<=128");for(int j=0;j<p.n;++j)if(!(std::isfinite(p.lb[j])&&p.lb[j]==p.ub[j]))free.push_back(j);else require(warm.x[j]==p.lb[j],"warm fixed coordinate mismatch");
  require(p.equalities.size()<=512&&p.inequalities.size()<=512,"native finisher row count exceeds bounded storage");std::size_t bound_sides=0;for(int j=0;j<p.n;++j){bound_sides+=std::isfinite(p.lb[j]);bound_sides+=std::isfinite(p.ub[j]);}require(free.size()+p.equalities.size()+p.inequalities.size()+bound_sides<=512,"native finisher total working dimension exceeds bounded storage");
  for(int i=0;i<(int)p.inequalities.size();++i){inequalities.push_back(p.inequalities[i]);kinds.push_back(0);origins.push_back(i);}for(int j=0;j<p.n;++j){auto bound=[&](double b,int side){QuadraticFunction q;q.constant=side<0?b:-b;q.linear.assign(p.n,0);q.linear[j]=side;q.hessian.n=p.n;inequalities.push_back(std::move(q));kinds.push_back(side);origins.push_back(j);};if(std::isfinite(p.lb[j]))bound(p.lb[j],-1);if(std::isfinite(p.ub[j]))bound(p.ub[j],1);}
  sf=1/std::max(1.,inf_norm(p.objective.gradient(warm.x)));for(const auto&q:p.equalities)hs.push_back(1/std::max(1.,inf_norm(q.gradient(warm.x))));for(const auto&q:inequalities)gs.push_back(1/std::max(1.,inf_norm(q.gradient(warm.x))));
 }
 State state(const Point& t)const {State s;const int nf=free.size();s.objective_gradient=p.objective.gradient(t.x);s.rd.resize(nf);for(int j=0;j<nf;++j)s.rd[j]=s.objective_gradient[free[j]];
  for(int e=0;e<(int)p.equalities.size();++e){s.h.push_back(p.equalities[e].value(t.x));auto g=p.equalities[e].gradient(t.x);s.jh.emplace_back(nf);for(int j=0;j<nf;++j){s.jh.back()[j]=g[free[j]];s.rd[j]+=t.lambda[e]*g[free[j]];}}
  for(int i=0;i<(int)inequalities.size();++i){s.g.push_back(inequalities[i].value(t.x));auto g=inequalities[i].gradient(t.x);s.jg.emplace_back(nf);for(int j=0;j<nf;++j){s.jg.back()[j]=g[free[j]];s.rd[j]+=t.z[i]*g[free[j]];}}return s;
 }
 Result payload(const Point&t)const {Result r;r.x=t.x;r.certificate_equality_multipliers=t.lambda;r.certificate_inequality_multipliers.assign(p.inequalities.size(),0);r.certificate_lower_multipliers.assign(p.n,0);r.certificate_upper_multipliers.assign(p.n,0);for(int i=0;i<(int)inequalities.size();++i){if(kinds[i]==0)r.certificate_inequality_multipliers[origins[i]]=t.z[i];else if(kinds[i]<0)r.certificate_lower_multipliers[origins[i]]=t.z[i];else r.certificate_upper_multipliers[origins[i]]=t.z[i];}const auto st=strict_settings();direct_original_audit(p,st,r);return r;}
 bool strict(const Result&r)const{return r.termination_audit_valid&&std::isfinite(r.feasibility.total_inf)&&r.feasibility.total_inf<=tolerance&&std::isfinite(r.dual_infeasibility_inf)&&r.dual_infeasibility_inf<=tolerance&&std::isfinite(r.complementarity_inf)&&r.complementarity_inf<=tolerance;}
 std::vector<int> active(const Point&t,const State&s)const {std::vector<int> a;for(int i=0;i<(int)inequalities.size();++i){const double norm=inf_norm(inequalities[i].gradient(t.x));if(inf_norm(s.jg[i])==0)continue;if((t.z[i]>tolerance/std::max(1.,norm)&&s.g[i]>=-std::sqrt(tolerance))||s.g[i]>tolerance)a.push_back(i);}return a;}
 Matrix rows(const State&s,const std::vector<int>&a)const {Matrix j=s.jh;for(int e=0;e<(int)j.size();++e)for(double&v:j[e])v*=hs[e];for(int i:a){j.push_back(s.jg[i]);for(double&v:j.back())v*=gs[i];}return j;}
 double merit(const Point&t,const State&s,const std::vector<int>&a)const {long double sum=0;auto add=[&](long double v){sum+=v*v;};for(double v:s.rd)add(sf*v);for(int e=0;e<(int)s.h.size();++e)add(hs[e]*s.h[e]);for(int i:a)add(gs[i]*s.g[i]);for(int i=0;i<(int)s.g.size();++i){add(gs[i]*std::max(0.,s.g[i]));add(std::min(0.,t.z[i]));add(sf*t.z[i]*s.g[i]);}return std::sqrt(sum);}
 Matrix hessian(const Point&t)const {const int nf=free.size();Matrix h(nf,Vec(nf));std::vector<int> index(p.n,-1);for(int j=0;j<nf;++j)index[free[j]]=j;auto add=[&](const QuadraticFunction&q,double weight){require(q.signed_square.empty(),"feasible finisher requires actual QCQP");for(auto e:q.hessian.entries){int i=index[e.i],j=index[e.j];if(i<0||j<0)continue;h[i][j]+=sf*weight*e.v;if(i!=j)h[j][i]+=sf*weight*e.v;}};add(p.objective,1);for(int e=0;e<(int)p.equalities.size();++e)add(p.equalities[e],t.lambda[e]);for(int i=0;i<(int)inequalities.size();++i)if(t.z[i]!=0)add(inequalities[i],t.z[i]);return h;}
};
// Linear least-squares auxiliary KKT. No normal equations, dense SVD or
// external optimizer; free equality variables and passive nonnegative rows.
Vec least_squares(Context&c,const Matrix&columns,const Vec&y,const std::vector<int>&passive){const int n=y.size(),m=passive.size();Matrix k(n+m,Vec(n+m));for(int j=0;j<n;++j)k[j][j]=1;for(int e=0;e<m;++e)for(int j=0;j<n;++j)k[j][n+e]=k[n+e][j]=columns[passive[e]][j];Vec rhs(n+m);std::copy(y.begin(),y.end(),rhs.begin());auto sol=c.solve(k,rhs,m,"dual-linear-LS");return Vec(sol.begin()+n,sol.end());}
Point fit(Context&c,const Problem&p,const Point&point,const std::vector<int>&active){++c.counts.dual_fit;const auto s=p.state(point);const Matrix columns=p.rows(s,active);const int ne=p.p.equalities.size(),m=columns.size(),nf=p.free.size();Vec y(nf);for(int j=0;j<nf;++j)y[j]=-p.sf*s.objective_gradient[p.free[j]];Vec values(m,0);std::vector<unsigned char> passive(m);for(int e=0;e<ne;++e)passive[e]=1;bool done=false;
 for(int iter=0;iter<100&&c.open();++iter){++c.counts.dual_basis;std::vector<int> indices;for(int e=0;e<m;++e)if(passive[e])indices.push_back(e);auto solved=least_squares(c,columns,y,indices);Vec proposal(m,0);for(int k=0;k<(int)indices.size();++k)proposal[indices[k]]=solved[k];double alpha=1;int drop=-1;for(int e=ne;e<m;++e)if(passive[e]&&proposal[e]<0){const double fraction=values[e]/(values[e]-proposal[e]);if(fraction<alpha){alpha=fraction;drop=e;}}
  if(drop>=0){for(int e=0;e<m;++e)values[e]+=alpha*(proposal[e]-values[e]);for(int e=ne;e<m;++e)if(passive[e]&&values[e]<=0){values[e]=0;passive[e]=0;}continue;}
  values=proposal;Vec residual(nf);for(int j=0;j<nf;++j){long double r=-y[j];for(int e=0;e<m;++e)r+=(long double)columns[e][j]*values[e];residual[j]=r;}
  double best=1e-12;int enter=-1;for(int e=ne;e<m;++e)if(!passive[e]){long double w=0;for(int j=0;j<nf;++j)w-=(long double)columns[e][j]*residual[j];if(w>best){best=w;enter=e;}}if(enter<0){done=true;break;}passive[enter]=1;
 }
 require(done&&c.open(),"bounded native nonnegative dual fit did not converge");Point out=point;out.lambda.resize(ne);out.z.assign(point.z.size(),0);for(int e=0;e<ne;++e)out.lambda[e]=p.hs[e]/p.sf*values[e];for(int j=0;j<(int)active.size();++j)out.z[active[j]]=p.gs[active[j]]/p.sf*std::max(0.,values[ne+j]);return out;}
struct Direction {Vec dx;double forcing=0,allowed=0;int dropped=0,negative=0;};
Direction original_direction(Context&c,const Problem&p,const Point&t,const State&s,const std::vector<int>&active){const int nf=p.free.size();const Matrix a=p.rows(s,active);const int m=a.size(),dim=nf+m;require(dim<=512,"native feasible KKT dimension exceeds small-system guard");Matrix k(dim,Vec(dim));auto h=p.hessian(t);for(int i=0;i<nf;++i)for(int j=0;j<nf;++j)k[i][j]=h[i][j];for(int e=0;e<m;++e)for(int j=0;j<nf;++j)k[j][nf+e]=k[nf+e][j]=a[e][j];Vec rhs(dim);for(int j=0;j<nf;++j)rhs[j]=-p.sf*s.rd[j];for(int e=0;e<(int)s.h.size();++e)rhs[nf+e]=-p.hs[e]*s.h[e];for(int j=0;j<(int)active.size();++j)rhs[nf+s.h.size()+j]=-p.gs[active[j]]*s.g[active[j]];
 const auto eigen=jacobi(k,[&](){return c.open();});const double norm=l2(rhs),eta=std::min(.2,std::sqrt(norm));double spectral=1;for(double v:eigen.values)spectral=std::max(spectral,std::abs(v));const double cap=std::sqrt(norm)*spectral,allowed=eta*norm;Vec coeff(dim);for(int j=0;j<dim;++j)for(int i=0;i<dim;++i)coeff[j]+=eigen.vectors[i][j]*rhs[i];std::vector<int> order(dim);std::iota(order.begin(),order.end(),0);std::stable_sort(order.begin(),order.end(),[&](int i,int j){return std::abs(eigen.values[i])<std::abs(eigen.values[j]);});std::vector<unsigned char> drop(dim);long double dropped2=0;for(int j:order){if(std::abs(eigen.values[j])>cap)break;const long double next=dropped2+(long double)coeff[j]*coeff[j];if(std::sqrt(next)>allowed)break;drop[j]=1;dropped2=next;}for(int j=0;j<dim;++j)if(std::abs(eigen.values[j])<=std::numeric_limits<double>::epsilon()*spectral)drop[j]=1;
 std::vector<int> discarded;int negative=0;long double discarded_rhs2=0;for(int j=0;j<dim;++j)if(drop[j]){discarded.push_back(j);discarded_rhs2+=(long double)coeff[j]*coeff[j];}else if(eigen.values[j]<0)++negative;require(std::sqrt(discarded_rhs2)<=std::max(allowed,100*std::numeric_limits<double>::epsilon()*norm),"native rank truncation exceeds original Newton forcing");
 const int q=discarded.size();Matrix bordered(dim+q,Vec(dim+q));for(int i=0;i<dim;++i)for(int j=0;j<dim;++j)bordered[i][j]=k[i][j];for(int j=0;j<q;++j)for(int i=0;i<dim;++i)bordered[i][dim+j]=bordered[dim+j][i]=eigen.vectors[i][discarded[j]];Vec brhs=rhs;brhs.resize(dim+q);auto sol=c.solve(bordered,brhs,negative+q,"signed-original-Newton-border");++c.counts.newton;Vec residual(dim);for(int i=0;i<dim;++i){long double r=-rhs[i];for(int j=0;j<dim;++j)r+=(long double)k[i][j]*sol[j];residual[i]=r;}const double forcing=l2(residual);require(forcing<=std::max(allowed,100*std::numeric_limits<double>::epsilon()*norm),"native original Newton forcing audit failed");c.counts.max_forcing_ratio=std::max(c.counts.max_forcing_ratio,forcing/std::max(allowed,1e-300));Direction d;d.dx.assign(p.p.n,0);for(int j=0;j<nf;++j)d.dx[p.free[j]]=sol[j];d.forcing=forcing;d.allowed=allowed;d.dropped=q;d.negative=negative;return d;
}
bool normal(Context&c,const Problem&p,Vec&x,const std::vector<int>&active,double predictor_norm){Vec total(p.p.n,0);for(int step=0;step<5;++step){require(c.open(),"normal deadline");Point t;t.x=x;t.lambda.assign(p.p.equalities.size(),0);t.z.assign(p.inequalities.size(),0);const auto s=p.state(t);double physical=inf_norm(s.h);for(int i:active)physical=std::max(physical,std::abs(s.g[i]));if(physical<=1e-10)return true;const auto a=p.rows(s,active);const int nf=p.free.size(),m=a.size();Matrix k(nf+m,Vec(nf+m));for(int j=0;j<nf;++j)k[j][j]=1;for(int e=0;e<m;++e)for(int j=0;j<nf;++j)k[j][nf+e]=k[nf+e][j]=a[e][j];Vec rhs(nf+m);for(int e=0;e<(int)s.h.size();++e)rhs[nf+e]=-p.hs[e]*s.h[e];for(int j=0;j<(int)active.size();++j)rhs[nf+s.h.size()+j]=-p.gs[active[j]]*s.g[active[j]];const auto sol=c.solve(k,rhs,m,"normal-original-retraction");++c.counts.normal;long double linear2=0,rhs2=0;for(int e=0;e<m;++e){long double residual=-rhs[nf+e];for(int j=0;j<nf;++j)residual+=(long double)a[e][j]*sol[j];linear2+=residual*residual;rhs2+=(long double)rhs[nf+e]*rhs[nf+e];}const double linear_residual=std::sqrt(linear2);c.counts.max_normal_linear_residual=std::max(c.counts.max_normal_linear_residual,linear_residual);if(linear_residual>std::max(1e-12,1e-8*double(std::sqrt(rhs2))))return false;Vec correction(p.p.n,0);for(int j=0;j<nf;++j)correction[p.free[j]]=sol[j];Vec next=total;axpy(1,correction,next);if(l2(next)>.5*predictor_norm)return false;Vec tx=x;axpy(1,correction,tx);if(tx==x)return false;x=std::move(tx);total=std::move(next);}
 Point t;t.x=x;t.lambda.assign(p.p.equalities.size(),0);t.z.assign(p.inequalities.size(),0);const auto s=p.state(t);double physical=inf_norm(s.h);for(int i:active)physical=std::max(physical,std::abs(s.g[i]));return physical<=1e-10;}
struct Outcome {Point point;Result result,private_trial;bool committed=false;std::string reason="private-step-budget";};
Outcome finish(Context&c,const Problem&p,const Point&primary,int max_steps){Outcome out;out.point=primary;out.result=p.payload(primary);out.private_trial=out.result;Point current=primary;for(int step=0;step<max_steps&&c.open();++step){const Result before_audit=p.payload(current);if(p.strict(before_audit)){out.committed=true;out.reason="strict-original-QCQP";break;}try{const auto initial_state=p.state(current);const auto active=p.active(current,initial_state);current=fit(c,p,current,active);const auto s=p.state(current);const double before=p.merit(current,s,active);const auto direction=original_direction(c,p,current,s,active);const double radius=.1*(1+l2(current.x))/std::sqrt(p.p.n);double alpha=std::min(1.,radius/std::max(l2(direction.dx),std::numeric_limits<double>::min()));bool accepted=false;Point trial=current;double after=INFINITY;Result audited;
 for(int ls=0;ls<32&&c.open();++ls,alpha*=.5){++c.counts.line_trials;Vec predictor=direction.dx;for(double&v:predictor)v*=alpha;trial=current;axpy(1,predictor,trial.x);if(!normal(c,p,trial.x,active,l2(predictor)))continue;trial=fit(c,p,trial,active);const auto ts=p.state(trial);after=p.merit(trial,ts,active);audited=p.payload(trial);if(audited.feasibility.total_inf<=std::max(1e-8,before_audit.feasibility.total_inf)&&after<(1-1e-4*alpha)*before){accepted=true;break;}}
 std::cout<<std::setprecision(17)<<"[FEASIBLE-ORIGINAL-KKT] step="<<step+1<<" accepted="<<accepted<<" alpha="<<alpha<<" active="<<active.size()<<" dropped="<<direction.dropped<<" retained_negative="<<direction.negative<<" linear_forcing="<<direction.forcing<<" forcing_allowed="<<direction.allowed<<" dx_l2="<<l2(direction.dx)<<" residual_before="<<before<<" residual_after="<<after<<" physical_feas="<<(accepted?audited.feasibility.total_inf:before_audit.feasibility.total_inf)<<" physical_dual="<<(accepted?audited.dual_infeasibility_inf:before_audit.dual_infeasibility_inf)<<" seconds="<<elapsed(c.started)<<" Cq=0 ordinary_DCA_acceptance=0 backend_shifts=0\n"<<std::flush;
 if(!accepted){out.reason="no-retracted-original-KKT-merit-contraction";break;}current=std::move(trial);out.private_trial=audited;if(p.strict(audited)&&c.open()){out.committed=true;out.reason="strict-original-QCQP";break;}
 }catch(const std::runtime_error&e){out.reason=e.what();break;}}
 if(!c.open()){out.committed=false;out.reason="private-deadline";}if(out.committed){out.point=current;out.result=p.payload(current);}return out;}
Vec read_vec(std::istream&f){std::uint64_t n;f.read(reinterpret_cast<char*>(&n),sizeof(n));require(n<=100000,"invalid warm vector length");Vec v(n);f.read(reinterpret_cast<char*>(v.data()),n*sizeof(double));require(bool(f)&&all_finite(v),"invalid warm vector");return v;}
Point read_warm(const std::string&path,const QCQPProblem&p,Result* raw=nullptr){std::ifstream f(path,std::ios::binary);char header[8];f.read(header,8);require(std::string(header,8)=="DCAEP001","invalid warm header");Point t;t.x=read_vec(f);t.lambda=read_vec(f);const auto zi=read_vec(f),lo=read_vec(f),up=read_vec(f);require(t.x.size()==std::size_t(p.n)&&t.lambda.size()==p.equalities.size()&&zi.size()==p.inequalities.size()&&lo.size()==std::size_t(p.n)&&up.size()==std::size_t(p.n),"warm dimensions mismatch");if(raw){raw->x=t.x;raw->certificate_equality_multipliers=t.lambda;raw->certificate_inequality_multipliers=zi;raw->certificate_lower_multipliers=lo;raw->certificate_upper_multipliers=up;}t.z=zi;for(int j=0;j<p.n;++j){if(std::isfinite(p.lb[j]))t.z.push_back(lo[j]);if(std::isfinite(p.ub[j]))t.z.push_back(up[j]);}return t;}
Result preserve_raw_primary(const QCQPProblem&p,Result raw){const auto settings=strict_settings();direct_original_audit(p,settings,raw,false);return raw;}
void unit(){QCQPProblem p;p.name="anonymous-common-phase-curved-constraints";p.n=4;const double a=.3,b=.31;p.x0={std::cos(a),std::sin(a),std::cos(b),std::sin(b)};p.lb.assign(4,-INFINITY);p.ub.assign(4,INFINITY);p.objective.linear.assign(4,0);p.objective.hessian.n=4;p.objective.hessian.entries={{0,0,2},{1,1,2},{2,2,2},{3,3,2},{0,2,-2},{1,3,-2}};for(int j=0;j<2;++j){QuadraticFunction h;h.constant=-1;h.linear.assign(4,0);h.hessian.n=4;h.hessian.entries={{2*j,2*j,2},{2*j+1,2*j+1,2}};p.equalities.push_back(h);}p.validate();Point primary{p.x0,{std::cos(.01)-1,std::cos(.01)-1},{}};Problem problem(p,primary);Context c(Clock::now(),5);auto out=finish(c,problem,primary,256);require(out.committed&&problem.strict(out.result),"anonymous curved normal finisher did not certify");Context expired(Clock::now(),0);auto rejected=finish(expired,problem,primary,256);require(!rejected.committed&&rejected.point.x==primary.x&&rejected.point.lambda==primary.lambda&&rejected.point.z==primary.z,"expired native finisher failed exact rollback");QCQPProblem too_many=p;too_many.equalities.resize(600,p.equalities[0]);bool storage_rejected=false;try{Problem guarded(too_many,primary);}catch(const std::runtime_error&){storage_rejected=true;}require(storage_rejected,"native finisher admitted unbounded constraint storage");QCQPProblem fixed=p;fixed.n=5;fixed.x0.push_back(2);fixed.lb.push_back(2);fixed.ub.push_back(2);fixed.objective.linear.push_back(0);fixed.objective.hessian.n=5;fixed.objective.hessian.entries.push_back({4,4,1});for(auto&h:fixed.equalities){h.linear.push_back(0);h.hessian.n=5;}Result raw;raw.x=fixed.x0;raw.certificate_equality_multipliers=primary.lambda;raw.certificate_inequality_multipliers={};raw.certificate_lower_multipliers={0,0,0,0,1000001};raw.certificate_upper_multipliers={0,0,0,0,1000000};const auto unchanged=preserve_raw_primary(fixed,raw);require(unchanged.x==raw.x&&unchanged.certificate_lower_multipliers==raw.certificate_lower_multipliers&&unchanged.certificate_upper_multipliers==raw.certificate_upper_multipliers,"fixed raw multipliers changed during rejection audit");std::cout<<"native_feasible_original_kkt_unit PASS newton="<<c.counts.newton<<" normal="<<c.counts.normal<<" dual_basis="<<c.counts.dual_basis<<std::endl;}
}
int main(int argc,char**argv){try{for(const char*k:{"OMP_NUM_THREADS","OMP_THREAD_LIMIT","OPENBLAS_NUM_THREADS","MKL_NUM_THREADS","BLIS_NUM_THREADS"})setenv(k,"1",1);
#ifdef _OPENMP
 omp_set_num_threads(1);
#endif
 if(argc==2&&std::string(argv[1])=="--self-test"){unit();return 0;}
 require(argc==7,"usage: finisher input.qcq warm.bin private_trial.json committed_or_primary.json report.json seconds");
 const auto began=Clock::now();const double requested_budget=std::stod(argv[6]);require(std::isfinite(requested_budget)&&requested_budget>=0,"invalid native finisher time budget");const double budget=std::min(60.,requested_budget);QCQPProblem p=read_qcq(argv[1]);
 require(p.n<=128,"small native finisher rejects n>128 before dense allocation");Result raw;
 Point primary=read_warm(argv[2],p,&raw);const auto preserved=preserve_raw_primary(p,raw);
 Problem problem(p,primary);Context c(began,budget);const auto out=finish(c,problem,primary,256);
 bool commit=out.committed&&c.open();Result trial=out.private_trial;
 trial.status=commit?Status::Solved:Status::MaxOuterIterations;
 trial.message="Explicit isolated feasible ORIGINAL-KKT finisher; signed Lagrangian, original functions unchanged, separate from ordinary DCA";
 write_result_json(trial,p.name,argv[3]);
 auto final=commit?out.result:preserved;final.status=commit?Status::Solved:Status::MaxOuterIterations;
 if(!c.open()){commit=false;final=preserved;final.status=Status::MaxOuterIterations;trial.status=Status::MaxOuterIterations;write_result_json(trial,p.name,argv[3]);}
 write_result_json(final,p.name,argv[4]);
 if(!c.open()){commit=false;final=preserved;final.status=Status::MaxOuterIterations;trial.status=Status::MaxOuterIterations;write_result_json(trial,p.name,argv[3]);write_result_json(final,p.name,argv[4]);}
 auto report=[&](){std::ofstream f(argv[5]);f<<std::setprecision(17)<<"{\"stage\":\"feasible_original_kkt_finisher\",\"committed_by_native\":"<<(commit?"true":"false")
 <<",\"reason\":\""<<(c.open()?out.reason:"private-deadline")<<"\",\"seconds_all_inclusive\":"<<elapsed(began)
 <<",\"Newton_directions\":"<<c.counts.newton<<",\"normal_directions\":"<<c.counts.normal<<",\"dual_fits\":"<<c.counts.dual_fit
 <<",\"dual_basis_solves\":"<<c.counts.dual_basis<<",\"factorizations\":"<<c.counts.factors<<",\"linear_solves\":"<<c.counts.solves
 <<",\"line_search_trials\":"<<c.counts.line_trials<<",\"max_expanded_linear_audit\":"<<c.counts.max_linear_audit
 <<",\"max_normal_linear_residual\":"<<c.counts.max_normal_linear_residual<<",\"max_original_Newton_forcing_ratio\":"<<c.counts.max_forcing_ratio
 <<",\"backend_shifts\":0,\"Cq\":0,\"ordinary_DCA_acceptance\":false,\"global_convexity_claimed\":false,\"production_enabled\":false}"<<std::endl;};
 report();if(commit&&!c.open()){commit=false;final=preserved;final.status=Status::MaxOuterIterations;trial.status=Status::MaxOuterIterations;write_result_json(trial,p.name,argv[3]);write_result_json(final,p.name,argv[4]);report();}
 return commit?0:1;
 }catch(const std::exception&e){std::cerr<<"[native feasible original KKT fatal] "<<e.what()<<std::endl;return 2;}}
